from abc import ABCMeta, abstractmethod
import six
from taf.internal.core import Group


@six.add_metaclass(ABCMeta)
class StartableComponent(object):
    """
    An object, that can be started and stopped.

    A startable component can either be a single startable object
    or a group of startable components.
    """

    @abstractmethod
    def start(self):
        """
        Start operating.
        """

    @abstractmethod
    def stop(self):
        """
        Stop operating.
        """


@six.add_metaclass(ABCMeta)
class StartableObject(StartableComponent):
    """
    Startable object.
    """

    def __init__(self, **kwargs):
        super(StartableObject, self).__init__(**kwargs)
        self._is_started = False

    def start(self):
        """
        Start operating.

        If the object has been started already, do nothing.
        """
        if self._is_started:
            return
        self._start()
        self._is_started = True

    @abstractmethod
    def _start(self):
        """
        Start operating.
        """

    def stop(self):
        """
        Stop operating.

        If the object is not started, do nothing.
        """
        if not self._is_started:
            return
        self._stop()
        self._is_started = False

    @abstractmethod
    def _stop(self):
        """
        Stop operating.
        """


class StartableGroup(StartableComponent, Group):
    """
    Group of startable components.
    """

    def start(self):
        """
        Start all members.
        """
        for member in self._members:
            member.start()

    def stop(self):
        """
        Stop all members.
        """
        for member in self._members:
            member.stop()
